const u=(v={})=>({id:'a',name:'规则训练员',en:'TRAINER',slug:'trainer',s:2,team:0,x:5,y:5,z:0,hp:1,maxhp:1,states:[],cc:15,bs:12,ph:11,wip:13,facing:0,weapon:'combi',loadout:['combi','cc'],...v});
const ftFixture=()=>{const units=[u(),u({id:'b',x:6}),u({id:'c',x:7})],f={id:'f',label:'HARIS 训练组',team:0,type:'HARIS',members:['a','b','c'],leaderId:'a',assignments:{a:{name:'A'},b:{name:'B',min:1},c:{name:'C'}}};return {units,fireteams:[f],f};};
export const FAQ_CASES=[
 {id:'target-position',title:'宣告细节与结算时的目标位置',pages:['Ballistic_Skills','Order_Expenditure_Sequence','White_Noise'],scope:'路径点、Z和姿态保留；宣告/结算界面另在实际对局验证。',run(check){const a=u(),b=u({id:'b',team:1,x:12,facing:180}),path=[{x:5,y:5,z:0,prone:false},{x:7,y:5,z:4,prone:true}],pts=F.declarationPoints(b,a,path,[],'combi','hit');check('结算候选点保留起点Z',pts[0].z,0);check('结算候选点保留终点Z',pts.at(-1).z,4);check('站立/俯卧不被终点姿态覆盖',[pts[0].prone,pts.at(-1).prone],[false,true]);}},
 {id:'marker-cover',title:'标记被命中，揭露后实际轮廓处于全掩体',pages:['Camouflaged_State','Mines','Multispectral_Visor','Traits','Transmutation'],scope:'已接入过保前揭露；复现遮住S0地雷的矮墙。其他孵化配置只在有实际轮廓数据时适用。',run(check){const a=u({msv:3}),b=D.entity(a,'shockMine',{x:9,y:5},1);b.id='b';b.team=1;const terrain=[{x:8,y:4,w:.2,h:2,height:.7}];check('S2标记可见',E.visibility(a,b,terrain).visible,true);const p=F.attackSavePlan(b,[5],15,F.weaponMode('combi'),false);p.attacker=a;F.revealSavingTarget(p,b,terrain);check('揭露后不再是迷彩标记',K.marker(b),false);check('实际S0被矮墙挡住',E.visibility(a,b,terrain).visible,false);check('清空过保次数和伤害',[p.initialCount,p.damage],[0,0]);}},
 {id:'coordinated-sd',title:'协同命令／饱和区不移除特殊骰SD',pages:['Coordinated_Orders','Saturation','Skills_and_Equipment_Module'],scope:'射速/特殊骰的规则算例；主比赛尚无完整协同命令编组与多人射击流程。',run(check){const a=u({bsSpecialDice:1}),m=F.weaponMode('hmg');const lead=F.adjustBurst(m.b,{coordinated:true,spearhead:true}),other=F.adjustBurst(m.b,{coordinated:true,spearhead:false});check('B4先锋减为B2',lead,2);check('其余成员B1',other,1);check('SD仍为1',F.specialDice(a,m),1);check('饱和后B1但仍掷2颗',[F.adjustBurst(lead,{saturation:true}),1+F.specialDice(a,m)],[1,2]);}},
 {id:'deployable-surface',title:'投射部署物必须完整支撑，不可贴垂直墙',pages:['Disco_Baller','Drop_Bears','Mine_Dispenser','Pitcher'],scope:'实际放置验证器；四类投射部署物共用完整支撑检查。',run(check){const a=u(),terrain=[{id:'roof',x:8,y:4,w:4,h:4,height:4,kind:'building'}];for(const id of ['discoBall','dropBears','shockMine','deployableRepeater']){check(id+'禁止垂直面',!!D.placement(a,id,{x:8,y:5,z:2,wall:'roof'},{ranged:true,terrain}).error,true);check(id+'合法水平屋顶',D.placement(a,id,{x:10,y:6,z:4},{ranged:true,terrain}).error,'');check(id+'不可悬空',!!D.placement(a,id,{x:7,y:6,z:4},{ranged:true,terrain}).error,true);}}},
 {id:'peripheral-idle',title:'控制者无法执行时，附属模型仍独立检查行动',pages:['Engaged_State','Immobilized-A_State','Immobilized-B_State','Peripheral','Stunned_State'],scope:'相同宣告、逐模型检查资格；可选择附属模型激活并使用控制者命令。',run(check){for(const state of ['stunned','immA','immB']){const a=u({states:[state]}),p=u({id:'p',peripheral:'ancillary',controllerId:'a',x:7});check(state+'控制者攻击待机',S.allowed(a,'attack'),false);check(state+'附属仍可攻击',S.allowed(p,'attack'),true);check(state+'仍属于同一激活组',P.partners(p,[a,p]).some(n=>n.id==='a'),true);}}},
 {id:'fireteam-minimum',title:'组建时的必选成员离组不自动解散',pages:['Fireteam_Integrity','Fireteams_Chart','FT_Master'],scope:'实际火力组离组逻辑；FT Master括号指定单位为例外。',run(check){const s=ftFixture();FT.leave(s,'b','FAQ训练');check('必选B离组后保留组',!!s.f.cancelled,false);check('剩余人数',s.f.members.length,2);const special=ftFixture();special.units[1].ftMasterFor=['trainer'];FT.leave(special,'b','FAQ训练');check('FT Master特殊限制会解散',special.f.cancelled,true);}},
 {id:'fireteam-type',title:'三人Haris减员后仍是Haris',pages:['Fireteam_Integrity','Fireteams_Chart','Fireteams:_Basic_Rules'],scope:'实际火力组类型与人数变化。',run(check){const s=ftFixture();FT.leave(s,'c','FAQ训练');check('人数变为2',s.f.members.length,2);check('类型仍为HARIS',s.f.type,'HARIS');check('减至1人时解散',FT.leave(s,'b','FAQ训练').length>0&&!!s.f.cancelled,true);}},
 {id:'device-firewall',title:'黑客设备防火墙遇孤立／Null失效',pages:['Firewall','Hacking_Device','Isolated_State'],scope:'实际通讯攻击修正；不把设备防火墙和独立TinBot混为一谈。',run(check){const a=u({hackingDevice:'HD'}),b=u({id:'b',team:1,x:7,hackingDevice:'HD',hackingFirewall:-3});check('正常设备防火墙',H.attackSpec(a,b,'spotlight').firewall,-3);check('孤立设备防火墙失效',H.attackSpec(a,{...b,states:['isolated']},'spotlight').firewall,0);check('昏迷设备防火墙失效',H.attackSpec(a,{...b,hp:0,states:['unconscious']},'spotlight').firewall,0);}},
 {id:'ancillary-killed',title:'从未部署的Ancillary不算击杀',pages:['ITS_FAQ','Peripheral'],scope:'任务击杀资格计算；不是所有ITS任务与机密卡的完整自动计分。',run(check){const a=u({peripheral:'ancillary',offTable:true});check('从未部署不算击杀',Q.killedForObjectives(a,{finished:true}),false);check('已部署且昏迷算击杀',Q.killedForObjectives({...a,offTable:false,placedOrderId:1,hp:0,states:['unconscious']},{finished:true}),true);check('已部署仍正常不算击杀',Q.killedForObjectives({...a,offTable:false,placedOrderId:1},{finished:true}),false);}}
];
export function runFAQCase(id){const item=FAQ_CASES.find(c=>c.id===id),rows=[];try{item.run((label,actual,expected)=>rows.push({label,actual,expected,pass:JSON.stringify(actual)===JSON.stringify(expected)}));}catch(e){rows.push({label:'运行异常',actual:e.message,expected:'无异常',pass:false});}return {id,pass:rows.length>0&&rows.every(r=>r.pass),rows};}
